Here's a class I wrote for a simple LRU cache using a dict and a list to track order, but it's O(n) on eviction. Can you refactor it to use collections.OrderedDict or a doubly linked list so get and put are O(1), and explain the tradeoffs?
class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}
        self.order = []
    def get(self, key):
        if key not in self.data:
            return -1
        self.order.remove(key)
        self.order.append(key)
        return self.data[key]
    def put(self, key, value):
        if key in self.data:
            self.order.remove(key)
        elif len(self.data) >= self.capacity:
            oldest = self.order.pop(0)
            del self.data[oldest]
        self.data[key] = value
        self.order.append(key)

